<template>
  <div class="flex flex-col gap-6">
    <!-- Metadata grid -->
    <Card>
      <CardContent class="pt-6">
        <div class="grid grid-cols-2 sm:grid-cols-3 gap-4">
          <LabeledEntityProject :project-id="record.project_id" />
          <LabeledValueIcon label="Provider" :value="providerLabel" :icon="LayersIcon" />
          <LabeledValueIcon label="Status" :icon="CircleDotIcon">
            <Badge :variant="getImportStatus(record.status).variant" size="sm" data-testid="import-details-status">
              {{ getImportStatus(record.status).label }}
            </Badge>
          </LabeledValueIcon>
          <LabeledEntityUser label="Uploaded By" :user-id="record.created_by" />
          <LabeledEntityDate label="Created At" :date="record.created_at" />
          <LabeledValueIcon label="Original File" :icon="FileTextIcon">
            <a
              :href="record.download_url"
              target="_blank"
              rel="noopener"
              class="font-medium underline underline-offset-2"
              data-testid="import-details-download-file"
            >
              {{ record.name }}
            </a>
          </LabeledValueIcon>
        </div>
      </CardContent>
    </Card>

    <!-- Status state display -->
    <State
      v-if="record.status === 'PENDING' || record.status === 'PROCESSING'"
      :title="record.status === 'PENDING' ? 'Pending' : 'Processing'"
      :description="
        record.status === 'PENDING'
          ? 'Import is queued and will start shortly.'
          : 'Importing canvasser interactions from CSV. This may take a few minutes.'
      "
      :icon="Spinner"
      icon-class="size-16 w-16"
    />

    <State
      v-else-if="record.status === 'SUCCESS'"
      title="Import Complete"
      description="Canvasser interactions have been imported successfully."
      :icon="CircleCheckIcon"
      icon-class="size-16 w-16 text-green-600"
    />

    <template v-else-if="record.status === 'FAILED'">
      <State
        title="Import Failed"
        :md-description="record.error_msg?.title || 'An error occurred while importing the file.'"
        :icon="CircleXIcon"
        icon-class="size-16 w-16 text-destructive"
      />
      <AppMarkdown
        v-if="record.error_msg?.details"
        :markdown="record.error_msg.details"
        class="text-sm text-muted-foreground mt-2"
      />
    </template>

    <!-- Summary stats -->
    <div v-if="isFinished" class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3 text-sm">
      <Card class="shadow-none">
        <CardContent class="flex flex-col items-center gap-1 p-4">
          <span class="text-2xl font-semibold" data-testid="import-details-all-rows-count">{{
            record.all_rows_count
          }}</span>
          <span class="text-xs text-muted-foreground">Total rows</span>
        </CardContent>
      </Card>
      <Card class="shadow-none">
        <CardContent class="flex flex-col items-center gap-1 p-4">
          <span class="text-2xl font-semibold text-green-600" data-testid="import-details-inserted-rows-count">{{
            record.inserted_rows_count
          }}</span>
          <span class="text-xs text-muted-foreground">Inserted</span>
        </CardContent>
      </Card>
      <Card class="shadow-none">
        <CardContent class="flex flex-col items-center gap-1 p-4">
          <span class="text-2xl font-semibold text-blue-600">{{ record.updated_rows_count }}</span>
          <span class="text-xs text-muted-foreground">Updated</span>
        </CardContent>
      </Card>
      <Card class="shadow-none">
        <CardContent class="flex flex-col items-center gap-1 p-4">
          <span class="text-2xl font-semibold text-destructive">{{ record.failed_rows_count }}</span>
          <span class="text-xs text-muted-foreground">Failed</span>
        </CardContent>
      </Card>
      <Card class="shadow-none">
        <CardContent class="flex flex-col items-center gap-1 p-4">
          <span class="text-2xl font-semibold text-orange-500">{{ record.filtered_rows_count }}</span>
          <span class="text-xs text-muted-foreground">Skipped</span>
        </CardContent>
      </Card>
    </div>

    <!-- Row events -->
    <RowEventsTable v-if="isFinished" :events="record.row_events" />
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';
import SpinnerSvg from '~/assets/icons/spinner.svg';
import { CircleCheckIcon, CircleXIcon, LayersIcon, CircleDotIcon, FileTextIcon } from 'lucide-vue-next';
import type { CanvassingInteractionImportDetailsResponse } from '~/client';
import { getImportStatus } from '~/constants/canvassing-interaction-imports/importStatusConfig';
import { getProjectCanvassingAppLabel } from '~/constants/projects/projectCanvassingAppLabel';

const props = defineProps<{
  record: CanvassingInteractionImportDetailsResponse;
}>();

const Spinner = SpinnerSvg;

const isFinished = computed(() => props.record.status === 'SUCCESS' || props.record.status === 'FAILED');

const providerLabel = computed(() => getProjectCanvassingAppLabel(props.record.target_provider));
</script>
