<template>
  <section class="flex flex-col gap-6">
    <PageTitle :title="data?.name ?? 'Import Details'">
      <NuxtLink :to="{ name: 'canvassing-interaction-imports' }">
        <Button variant="outline">Back to Imports</Button>
      </NuxtLink>
      <Button v-if="isFinished" data-testid="import-details-upload-another-btn" @click="uploadAnother = true">
        Upload Another File
      </Button>
    </PageTitle>

    <Card>
      <CardContent class="flex flex-col gap-6 pt-6">
        <AppLoader v-if="isLoading" subject="import details" variant="inline" />
        <AppError v-else-if="error" variant="table" title="Failed to check import status" />
        <ImportDetails v-else-if="data" :record="data" />
      </CardContent>
    </Card>

    <UploadModal v-model="uploadAnother" @uploaded="onUploaded" />
  </section>
</template>

<script setup lang="ts">
import { getCanvassingInteractionImportDetails, type GetCanvassingInteractionImportDetailsResponse } from '~/client';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'import',
});

useHead({
  title: 'Import Details',
});

const route = useRoute('canvassing-interaction-imports-importId');
const router = useRouter();
const importId = computed(() => route.params.importId as string);

const uploadAnother = ref(false);

const { data, refetch, isLoading, error } = useQuery({
  key: () => ['canvassing-interaction-import-details', importId.value],
  query: (): Promise<GetCanvassingInteractionImportDetailsResponse> =>
    getCanvassingInteractionImportDetails({
      composable: '$fetch',
      path: { import_id: importId.value },
    }),
  staleTime: 0,
  enabled: () => Boolean(importId.value),
});

const isFinished = computed(() => data.value?.status === 'SUCCESS' || data.value?.status === 'FAILED');

useTimeoutPoll(async () => {
  if (isFinished.value || error.value) return;
  await refetch().catch((err) => {
    console.error('Failed to check import status:', err);
  });
}, 5000);

async function onUploaded(newImportId: string) {
  await router.push({
    name: 'canvassing-interaction-imports-importId',
    params: { importId: newImportId },
  });
}
</script>
