<template>
  <div v-if="errorEvents.length > 0" class="flex flex-col gap-2">
    <span class="text-sm font-medium text-destructive" data-testid="row-events-error-heading">
      Errors ({{ errorEvents.length }})
    </span>
    <Card class="shadow-none">
      <ResponsiveTable rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
          <ResponsiveTableHead>Issue</ResponsiveTableHead>
          <ResponsiveTableHead>Value</ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="event in errorEventsPage"
            :key="`error-${event.row_number}-${event.validation_type}`"
            :data-testid="`row-event-error-${event.row_number}`"
          >
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">{{
              event.row_number
            }}</ResponsiveTableCell>
            <ResponsiveTableCell :cols="3" :cols-sm="3" label="Issue" class="text-xs">{{
              getValidationTypeLabel(event.validation_type)
            }}</ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">{{
              event.input_value ?? '—'
            }}</ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
      </ResponsiveTable>
    </Card>
    <div
      v-if="errorEvents.length > 25"
      class="flex items-center justify-end gap-2"
      data-testid="row-events-error-pagination"
    >
      <Button variant="outline" size="sm" :disabled="errorPage === 1" @click="errorPage -= 1"> Previous </Button>
      <span class="text-xs text-muted-foreground"> Page {{ errorPage }} of {{ errorTotalPages }} </span>
      <Button variant="outline" size="sm" :disabled="errorPage >= errorTotalPages" @click="errorPage += 1">
        Next
      </Button>
    </div>
  </div>

  <div v-if="warningEvents.length > 0" class="flex flex-col gap-2">
    <span class="text-sm font-medium text-orange-500" data-testid="row-events-warning-heading">
      Warnings ({{ warningEvents.length }})
    </span>
    <Card class="shadow-none">
      <ResponsiveTable rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
          <ResponsiveTableHead>Issue</ResponsiveTableHead>
          <ResponsiveTableHead>Value</ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="event in warningEventsPage"
            :key="`warn-${event.row_number}-${event.validation_type}`"
            :data-testid="`row-event-warning-${event.row_number}`"
          >
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">{{
              event.row_number
            }}</ResponsiveTableCell>
            <ResponsiveTableCell :cols="3" :cols-sm="3" label="Issue" class="text-xs">{{
              getValidationTypeLabel(event.validation_type)
            }}</ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">{{
              event.input_value ?? '—'
            }}</ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
      </ResponsiveTable>
    </Card>
    <div
      v-if="warningEvents.length > 25"
      class="flex items-center justify-end gap-2"
      data-testid="row-events-warning-pagination"
    >
      <Button variant="outline" size="sm" :disabled="warningPage === 1" @click="warningPage -= 1"> Previous </Button>
      <span class="text-xs text-muted-foreground"> Page {{ warningPage }} of {{ warningTotalPages }} </span>
      <Button variant="outline" size="sm" :disabled="warningPage >= warningTotalPages" @click="warningPage += 1">
        Next
      </Button>
    </div>
  </div>

  <div v-if="filteredEvents.length > 0" class="flex flex-col gap-2">
    <span class="text-sm font-medium text-muted-foreground" data-testid="row-events-filtered-heading">
      Skipped rows ({{ filteredEvents.length }})
    </span>
    <Card class="shadow-none">
      <ResponsiveTable rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead class="w-16">Row</ResponsiveTableHead>
          <ResponsiveTableHead>Reason</ResponsiveTableHead>
          <ResponsiveTableHead>Value</ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableRow
            v-for="event in filteredEventsPage"
            :key="`skip-${event.row_number}-${event.validation_type}`"
            :data-testid="`row-event-filtered-${event.row_number}`"
          >
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="Row" class="font-mono text-xs">{{
              event.row_number
            }}</ResponsiveTableCell>
            <ResponsiveTableCell :cols="3" :cols-sm="3" label="Reason" class="text-xs">{{
              getValidationTypeLabel(event.validation_type)
            }}</ResponsiveTableCell>
            <ResponsiveTableCell :cols="4" :cols-sm="4" label="Value" class="text-xs text-muted-foreground">{{
              event.input_value ?? '—'
            }}</ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
      </ResponsiveTable>
    </Card>
    <div
      v-if="filteredEvents.length > 25"
      class="flex items-center justify-end gap-2"
      data-testid="row-events-filtered-pagination"
    >
      <Button variant="outline" size="sm" :disabled="filteredPage === 1" @click="filteredPage -= 1"> Previous </Button>
      <span class="text-xs text-muted-foreground"> Page {{ filteredPage }} of {{ filteredTotalPages }} </span>
      <Button variant="outline" size="sm" :disabled="filteredPage >= filteredTotalPages" @click="filteredPage += 1">
        Next
      </Button>
    </div>
  </div>

  <div v-if="events.length === 0" class="text-sm text-muted-foreground text-center py-4" data-testid="row-events-empty">
    No row events recorded.
  </div>
</template>

<script setup lang="ts">
import { computed, ref } from 'vue';
import type { RowEvent } from '~/client';
import { getValidationTypeLabel } from '~/constants/canvassing-interaction-imports/validationTypeLabels';

const PAGE_SIZE = 25;

const props = defineProps<{
  events: RowEvent[];
}>();

const errorEvents = computed(() => props.events.filter((e) => e.event_type === 'error'));
const warningEvents = computed(() => props.events.filter((e) => e.event_type === 'warning'));
const filteredEvents = computed(() => props.events.filter((e) => e.event_type === 'filtered'));

const errorPage = ref(1);
const warningPage = ref(1);
const filteredPage = ref(1);

function paginate<T>(items: T[], page: number): T[] {
  const start = (page - 1) * PAGE_SIZE;
  return items.slice(start, start + PAGE_SIZE);
}

const errorEventsPage = computed(() => paginate(errorEvents.value, errorPage.value));
const warningEventsPage = computed(() => paginate(warningEvents.value, warningPage.value));
const filteredEventsPage = computed(() => paginate(filteredEvents.value, filteredPage.value));

const errorTotalPages = computed(() => Math.max(1, Math.ceil(errorEvents.value.length / PAGE_SIZE)));
const warningTotalPages = computed(() => Math.max(1, Math.ceil(warningEvents.value.length / PAGE_SIZE)));
const filteredTotalPages = computed(() => Math.max(1, Math.ceil(filteredEvents.value.length / PAGE_SIZE)));
</script>
