import type { ComModelCanvassingInteractionImportImportRecordRowValidationType } from '~/client';

type ValidationType = ComModelCanvassingInteractionImportImportRecordRowValidationType;

const validationTypeLabels: Record<ValidationType, string> = {
  missing_required_column: 'Missing Required Column',
  missing_required_field: 'Missing Required Field',
  invalid_timestamp: 'Invalid Timestamp',
  invalid_float: 'Invalid Number',
  invalid_interaction_result: 'Invalid Interaction Result',
  missing_qa_for_survey: 'Missing Q&A For Survey',
  canvasser_not_found: 'Canvasser Not Found',
  workshift_not_found: 'Work Shift Not Found',
  campaign_id_mismatch: 'Campaign Id Mismatch',
  inconsistent_group: 'Inconsistent Group',
};

export function getValidationTypeLabel(type: ValidationType): string {
  return validationTypeLabels[type] ?? snakeCaseToCapitalizedCase(type);
}
